-- 0262 — Academy niveau 3, leçon 2 recentrée : figures à trois bougies et séances réelles (2026-11-24).
--
-- Demande de l’exploitant : la leçon 1 présente désormais l’anatomie de la
-- bougie et six figures (0261) ; la leçon 2 est recentrée sur un
-- approfondissement :
--   · les quatre figures à trois bougies (étoile du matin, étoile du soir,
--     trois soldats blancs, trois corbeaux noirs), chacune avec un atelier
--     de bougies modifiables (simulateur « figure_bougies ») ;
--   · les règles de repérage écrites noir sur blanc (aucun écart d’ouverture
--     exigé : l’ouverture égale la clôture de la veille dans 40,9 % des
--     séances de la BRVM depuis 2021) ;
--   · les VRAIES bougies des dernières séances de six valeurs, figures
--     repérées et datées (simulateur « bougies », /api/academy/serie) ;
--   · ce que montrent 4 923 bougies réelles de 2021 à 2026 : aucune figure
--     ne fait nettement mieux qu’une séance quelconque dans le sens de sa
--     lecture (intervalles de Wilson à 95 %, au moins 30 cas).
-- Source : frontend/lib/academy/contenus/niveau3/l02-chandeliers.json, générée
-- par frontend/scripts/academy-lecon2-bougies.mjs depuis
-- niveau3/sources/bougies-brvm-2026-11-24.json (scripts/academy-lecon2-stats.mjs,
-- règles de lib/academy/figuresBougies.ts). Testée : niveaux3-4.test.ts.
--
-- ⚠️ ORDRE : APRÈS le déploiement du frontend qui connaît les simulateurs
-- « bougies » et « figure_bougies ». Sans lui, courseContentSchema refuse le
-- cours et TOUT le niveau 3 répond 404.
--
-- Remplacement de la seule position 2 (leçon 0 en 0, leçon 1 en 1), gardée par
-- titre (ancien OU nouveau) ; l’ordre des leçons ne change pas, la progression
-- reste valide. Fusion || : les clés absentes du fichier (image…) sont
-- conservées. Idempotente. Aucun schéma ne change ; aucune donnée personnelle.

begin;

do $do$
declare
  v_titre text;
begin
  select content->'lessons'->2->>'titre' into v_titre
    from public.academy_courses where slug = 'academy-niveau-3-technique' for update;
  if v_titre is null or v_titre not like 'Leçon 2 — Les chandeliers japonais%' then
    raise exception '0262 : position 2 inattendue (%)', v_titre;
  end if;

  update public.academy_courses
     set content = jsonb_set(content, '{lessons,2}', (content->'lessons'->2) || $wb${"titre":"Leçon 2 — Les chandeliers japonais : figures à trois bougies et séances réelles","module":"Module 1 — Graphiques et tendances","categorie":"technical","duree_min":16,"sous_titre":"Après les bougies isolées de la leçon 1 : les figures à trois bougies, leur lecture sur les vraies séances de la BRVM, et ce que l’historique en dit.","resume":"La leçon 1 a posé l’anatomie d’une bougie et six figures à une ou deux bougies. Celle-ci approfondit : les quatre figures à trois bougies (étoile du matin, étoile du soir, trois soldats blancs, trois corbeaux noirs), les règles exactes que WESTBOURSE applique pour les repérer, leur lecture sur les dernières séances réelles des valeurs les plus échangées, et ce que montrent 4 923 bougies réelles de la BRVM depuis 2021.","nouveaute":{"type":"mis_a_jour","depuis":"2026-11-24"},"sections":[{"type":"definition","titre":"Ce que la leçon 1 a posé, ce que celle-ci ajoute","contenu":"Une bougie résume une séance en quatre prix : ouverture, plus haut, plus bas, clôture. Le corps va de l’ouverture à la clôture ; sur WESTBOURSE, il est clair et vert quand la séance monte, plein et rouge quand elle baisse. Les mèches montrent jusqu’où le cours est allé avant de revenir.\nLa leçon 1 a présenté six figures à une ou deux bougies : le doji, le marteau, l’étoile filante, les deux avalements et le harami. Cette leçon passe aux figures à trois bougies, puis quitte les exemples pour les vraies séances : comment lire les bougies des valeurs de la BRVM, et ce que leur historique permet, ou ne permet pas, de conclure.","points":[{"titre":"Le corps : ouverture et clôture","detail":"Un grand corps, une séance dominée par un camp ; un petit corps, de l’hésitation."},{"titre":"Les mèches : les extrêmes","detail":"Une longue mèche montre un prix atteint puis repoussé."},{"titre":"Une figure décrit, elle ne prédit pas","detail":"Elle raconte une ou plusieurs séances passées."},{"titre":"Le volume d’abord","detail":"Une bougie sans échange, ou faite de quelques titres, ne contient presque rien."}]},{"type":"definition","titre":"L’étoile du matin et l’étoile du soir","contenu":"Les figures à trois bougies racontent une petite histoire en trois actes. L’étoile du matin commence par une grande séance de baisse ; la deuxième séance hésite, avec un petit corps, dans le bas de la première ; la troisième monte et clôture au-dessus du milieu du corps de la première. Les vendeurs dominaient, ils ont marqué le pas, les acheteurs ont repris plus de la moitié du terrain.\nL’étoile du soir est son miroir : une grande hausse, une séance d’hésitation dans le haut de la première, puis une baisse qui efface plus de la moitié de la hausse. Les deux ateliers ci-dessous dessinent ces figures ; modifiez un prix et regardez à quel moment la figure disparaît.","tableau":{"colonnes":["Figure","Séance 1","Séance 2","Séance 3","Lecture courante"],"lignes":[["Étoile du matin","Grande baissière","Petit corps, dans le bas du corps de la séance 1","Haussière qui clôture au-dessus du milieu du corps de la séance 1","Retournement à la hausse"],["Étoile du soir","Grande haussière","Petit corps, dans le haut du corps de la séance 1","Baissière qui clôture sous le milieu du corps de la séance 1","Retournement à la baisse"],["Trois soldats blancs","Haussière franche","Haussière franche, ouverte dans le corps de la veille","Haussière franche, clôture la plus haute","Poursuite de la hausse"],["Trois corbeaux noirs","Baissière franche","Baissière franche, ouverte dans le corps de la veille","Baissière franche, clôture la plus basse","Poursuite de la baisse"]],"note":"La « lecture courante » est celle de la tradition de l’analyse technique. La section « Ce que les bougies de la BRVM nous apprennent » montre ce qu’elle vaut sur nos séances."},"simulations":[{"type":"figure_bougies","consigne":"L’étoile du matin : baissez la clôture de la troisième séance sous 985 FCFA, la figure disparaît.","bougies":[{"ouverture":1000,"haut":1002,"bas":968,"cloture":970},{"ouverture":970,"haut":974,"bas":962,"cloture":968},{"ouverture":968,"haut":992,"bas":966,"cloture":990}]},{"type":"figure_bougies","consigne":"L’étoile du soir : le miroir de la précédente. Agrandissez le corps de la deuxième séance : ce n’est plus une hésitation.","bougies":[{"ouverture":1000,"haut":1032,"bas":998,"cloture":1030},{"ouverture":1030,"haut":1038,"bas":1026,"cloture":1032},{"ouverture":1032,"haut":1034,"bas":1006,"cloture":1008}]}]},{"type":"definition","titre":"Trois soldats blancs et trois corbeaux noirs","contenu":"Les trois soldats blancs sont trois séances de hausse franche à la suite : chaque corps occupe l’essentiel de la séance, chaque clôture dépasse la précédente, chaque ouverture se fait dans le corps de la veille ou à sa clôture. Les trois corbeaux noirs sont la même figure à la baisse.\nCes deux figures décrivent une poursuite plutôt qu’un retournement : un camp a dominé trois séances de suite. Elles demandent des corps nets ; trois petites hausses de quelques francs ne font pas trois soldats. Les ateliers ci-dessous le montrent : réduisez un seul corps et la figure tombe.","simulations":[{"type":"figure_bougies","consigne":"Trois soldats blancs : réduisez le corps de la deuxième séance à quelques francs, la figure disparaît.","bougies":[{"ouverture":1000,"haut":1011,"bas":999,"cloture":1010},{"ouverture":1010,"haut":1021,"bas":1009,"cloture":1020},{"ouverture":1020,"haut":1031,"bas":1019,"cloture":1030}]},{"type":"figure_bougies","consigne":"Trois corbeaux noirs : la même figure, à la baisse.","bougies":[{"ouverture":1030,"haut":1031,"bas":1019,"cloture":1020},{"ouverture":1020,"haut":1021,"bas":1009,"cloture":1010},{"ouverture":1010,"haut":1011,"bas":999,"cloture":1000}]}]},{"type":"importance","titre":"Les règles de repérage, écrites noir sur blanc","contenu":"Les noms des figures sont anciens ; leurs définitions varient d’un livre à l’autre. Pour lire de vraies séances, il faut des règles précises, sinon chacun voit la figure qu’il souhaite voir. Voici celles qu’appliquent les ateliers et le simulateur de cette leçon, et la mesure qui suit.\nUne différence avec les manuels : aucun écart d’ouverture (gap) n’est exigé entre les bougies. Sur les grands marchés, l’étoile du matin suppose souvent que la deuxième séance ouvre en dessous de la clôture de la première. À la BRVM, l’ouverture est égale à la clôture de la veille dans 40,9 % des séances depuis 2021 : la définition classique ne s’y rencontrerait presque jamais.","tableau":{"colonnes":["Notion","Règle appliquée"],"lignes":[["Bougie lisible","Ouverture, plus haut, plus bas et clôture publiés et cohérents, et des titres échangés. Sinon, la séance n’est jamais lue comme une figure."],["Grande bougie","Corps d’au moins 1 % du cours d’ouverture et d’au moins la moitié de l’amplitude de la séance."],["Petite bougie","Corps d’au plus 30 % de celui de la grande bougie de référence."],["Doji, marteau, étoile filante","Mêmes seuils que le simulateur de la leçon 1 : corps d’au plus 10 % de l’amplitude ; mèche « longue » d’au moins deux fois le corps."],["Trois soldats, trois corbeaux","Trois corps d’au moins la moitié de l’amplitude et de 0,5 % du cours, clôtures successives plus hautes (ou plus basses)."],["Chevauchement","Une même figure ne réutilise jamais une séance déjà comptée : cinq baisses de suite font un « trois corbeaux », pas trois."]]},"stats":[{"label":"Ouvertures égales à la clôture de la veille","valeur":"40,9 %","detail":"10 357 séances sur 25 330, toutes actions, 2021-2026"},{"label":"Séances sans prix complets publiés","valeur":"59,9 %","detail":"38 159 sur 63 676 : aucune bougie n’y est lisible"}]},{"type":"cas","titre":"Lire les bougies sur des séances réelles","reel":true,"contenu":"Le simulateur ci-dessous affiche les vraies bougies des dernières séances d’une valeur, telles qu’elles sont publiées, et numérote les figures que les règles repèrent. Lisez-les dans cet ordre, sur chaque valeur.\nUne séance sans bougie lisible apparaît en pointillés : prix non publiés ou aucun échange. N’y cherchez rien. Le bloc en direct, en dessous, donne pour les mêmes valeurs le dernier cours, ses moyennes et le RSI : la figure se lit toujours dans ce contexte.","etapes":[{"titre":"Vérifier que la bougie est lisible","detail":"Prix publiés, titres échangés : une séance en pointillés ne contient aucune information."},{"titre":"Situer la tendance des séances précédentes","detail":"Une étoile du matin n’a de sens qu’après une baisse ; trois soldats, qu’en partant d’un niveau."},{"titre":"Nommer la figure, avec les règles de la leçon","detail":"Pas d’à-peu-près : si une condition manque, ce n’est pas la figure.","cle":true},{"titre":"Regarder le volume","detail":"Une figure faite de quelques titres ne pèse rien."},{"titre":"Attendre la séance suivante","detail":"La figure décrit le passé ; la séance suivante dit si le mouvement continue.","cle":true}],"simulation":{"type":"bougies","consigne":"Choisissez une valeur et le nombre de séances : les figures repérées sont numérotées au-dessus des bougies et listées en dessous, avec leur date.","codes":["SNTS","SGBC","ORAC","SIBC","BOAC","ETIT"],"seances":30},"donnees_reelles":{"vue":"technique","codes":["SNTS","SGBC","ORAC","SIBC"]}},{"type":"importance","titre":"Ce que les bougies de la BRVM nous apprennent","contenu":"Nous avons appliqué ces règles aux séances des dix actions les plus échangées, de 2021 au 23 novembre 2026 : 12 758 séances, dont 4 923 seulement ont une bougie lisible (38,6 %), faute de prix publiés pour les autres. Pour chaque figure, une question simple : cinq séances plus tard, le cours avait-il bougé dans le sens que lui prête la tradition ?\nLe point de comparaison est une séance quelconque : sur toutes les bougies lisibles, la clôture était plus haute cinq séances plus tard dans 43,9 % des cas, plus basse dans 42,0 %, inchangée dans 14,1 %. Une figure n’apporte quelque chose que si elle fait nettement mieux que ces parts.\nAucune n’y parvient : les 5 figures assez fréquentes pour être mesurées restent toutes dans l’intervalle de hasard. L’avalement baissier a même été suivi d’une baisse moins souvent qu’une séance quelconque (33,6 % contre 42,0 %, sur 125 cas). Le harami, la figure la plus fréquente (613 cas), ne se distingue pas non plus.\nCette mesure a ses limites : 5 comparaisons au seuil de 95 % laissent environ 23 % de chances qu’un écart apparaisse par pur hasard, les cas proches dans le temps ne sont pas dédoublonnés, et une moyenne recouvre des situations très différentes. Elle suffit pourtant à une conclusion : à la BRVM, une figure de chandeliers ne prédit pas, à elle seule, la suite du cours.","stats":[{"label":"Bougies lisibles","valeur":"4 923","detail":"sur 12 758 séances, dix valeurs, 2021-2026"},{"label":"Hausse 5 séances après une séance quelconque","valeur":"43,9 %","detail":"baisse 42,0 %, inchangé 14,1 %"},{"label":"Figures assez fréquentes pour être mesurées","valeur":"5","detail":"au moins 30 cas suivis de 5 séances"},{"label":"Écarts établis dans le sens de la figure","valeur":"0","detail":"intervalle à 95 % hors de la part d’une séance quelconque"}],"tableau":{"colonnes":["Figure","Cas mesurés","Sens attendu","Part, 5 séances après","Séance quelconque","Intervalle à 95 %","Verdict"],"lignes":[["Doji","16","Aucun (part de hausses)","12,5 %","43,9 %","3,5 à 36,0 %","Trop peu de cas (moins de 30)"],["Marteau","2","Hausse","0,0 %","43,9 %","0,0 à 65,8 %","Trop peu de cas (moins de 30)"],["Étoile filante","3","Baisse","33,3 %","42,0 %","6,1 à 79,2 %","Trop peu de cas (moins de 30)"],["Avalement haussier","128","Hausse","39,1 %","43,9 %","31,0 à 47,7 %","Écart non établi"],["Avalement baissier","125","Baisse","33,6 %","42,0 %","25,9 à 42,3 %","Écart non établi"],["Harami","608","Aucun (part de hausses)","42,8 %","43,9 %","38,9 à 46,7 %","Écart non établi"],["Étoile du matin","42","Hausse","38,1 %","43,9 %","25,0 à 53,2 %","Écart non établi"],["Étoile du soir","53","Baisse","41,5 %","42,0 %","29,3 à 54,9 %","Écart non établi"],["Trois soldats blancs","24","Hausse","50,0 %","43,9 %","31,4 à 68,6 %","Trop peu de cas (moins de 30)"],["Trois corbeaux noirs","24","Baisse","41,7 %","42,0 %","24,5 à 61,2 %","Trop peu de cas (moins de 30)"]],"note":"Part des cas où la clôture, 5 séances après la dernière bougie de la figure, était dans le sens attendu (hausse pour les figures haussières et d’indécision, baisse pour les baissières). Intervalle de Wilson à 95 %. Sources : séances de la BRVM de 2021 au 23/11/2026, ouverture, plus haut, plus bas et clôture des dix actions les plus échangées (base WESTBOURSE, lue le 24/11/2026) ; figures repérées et calculs WESTBOURSE."},"graphiques":[{"type":"bar","titre":"Après la figure, le mouvement attendu s’est-il produit plus souvent ? (%, figures d’au moins 30 cas)","labels":["Avalement haussier","Avalement baissier","Harami","Étoile du matin","Étoile du soir"],"series":[{"nom":"Après la figure","valeurs":[39.1,33.6,42.8,38.1,41.5]},{"nom":"Séance quelconque","valeurs":[43.9,42,43.9,43.9,42]}],"unite":"%","note":"Les barres restent proches : aucune figure ne fait nettement mieux qu’une séance quelconque dans le sens de sa lecture. Sources : séances de la BRVM de 2021 au 23/11/2026, ouverture, plus haut, plus bas et clôture des dix actions les plus échangées (base WESTBOURSE, lue le 24/11/2026) ; figures repérées et calculs WESTBOURSE.","reel":true}],"encadres":[{"ton":"cle","titre":"Ce que cela veut dire pour vous","texte":"Une figure de chandeliers reste utile pour décrire une séance et repérer un rejet ou une hésitation. Elle ne justifie pas, à elle seule, un achat ou une vente : la grille de décision de la leçon 0 demande toujours le contexte, les niveaux, le volume et un niveau d’invalidation."}]},{"type":"piege","titre":"Les chandeliers à la BRVM","contenu":"Une bougie suppose une séance active, avec de nombreux échanges répartis dans la journée. Sur un grand marché, les mèches reflètent des milliers d’ordres. À la BRVM, une séance peut ne compter que quelques transactions sur une valeur.\nConséquence directe : la forme d’une bougie peut venir d’un seul ordre. Une longue mèche basse, qui ressemblerait à un marteau sur un marché liquide, peut n’être qu’un vendeur pressé qui a accepté un prix bas pour quelques titres. La forme est là ; l’information derrière est très mince.\nLes données posent une autre difficulté : depuis 2021, 59,9 % des séances en base n’ont pas d’ouverture, de plus haut et de plus bas publiés. Plutôt que de dessiner des mèches inventées, WESTBOURSE affiche alors la clôture seule, et le signale. Une bougie sans vraies données derrière elle n’apprend rien et peut tromper.","points":[{"titre":"Une bougie sans échange","detail":"Sans transaction, la bougie est plate et ne dit rien.","verifier":"Le volume de la séance."},{"titre":"Peu d’ordres, beaucoup de forme","detail":"Avec quelques échanges, une longue mèche peut venir d’un seul ordre isolé.","verifier":"Le nombre de titres échangés."},{"titre":"Des données incomplètes","detail":"59,9 % des séances depuis 2021 n’ont pas de prix complets : WESTBOURSE n’y dessine aucune bougie.","verifier":"La mention de la source sous le graphique."},{"titre":"Des ouvertures sans écart","detail":"L’ouverture égale la clôture de la veille dans 40,9 % des séances : les figures qui exigent un gap n’existent presque pas ici."}]},{"type":"retenir","titre":"L’essentiel","contenu":"Une bougie raconte une séance ; une figure en raconte trois au plus. Ni l’une ni l’autre ne prédit la suivante : sur les séances réelles de la BRVM, aucune figure n’a fait nettement mieux qu’une séance quelconque.","points":[{"titre":"Quatre figures à trois bougies","detail":"Étoile du matin, étoile du soir, trois soldats blancs, trois corbeaux noirs."},{"titre":"Des règles écrites","detail":"Sans règles précises, chacun voit la figure qu’il souhaite voir."},{"titre":"Une bougie lisible d’abord","detail":"Prix publiés et titres échangés, sinon on ne lit rien."},{"titre":"Mesurer avant de croire","detail":"Sur la BRVM, aucune figure n’a montré d’avantage établi à cinq séances."}]}],"quiz":[{"question":"De quoi se compose une étoile du matin ?","options":["Trois hausses franches de suite, chacune clôturant plus haut que la précédente et ouvrant dans le corps de la veille","Une petite bougie contenue dans le corps d’une grande","Une grande baisse, une séance hésitante, puis une hausse qui reprend plus de la moitié de la baisse","Une seule bougie à longue mèche basse"],"correct":2,"explication":"Trois bougies : une grande baissière, une petite bougie d’hésitation, puis une haussière qui clôture au-dessus du milieu du corps de la première."},{"question":"Trois baisses franches de suite, chacune clôturant plus bas que la précédente et ouvrant dans le corps de la veille : quelle figure ?","options":["Trois corbeaux noirs","Une étoile du soir","Un harami suivi d’un doji","Trois soldats blancs"],"correct":0,"explication":"Trois corbeaux noirs : le miroir des trois soldats blancs. Aucune des deux figures ne dit ce que fera la séance suivante."},{"question":"Pourquoi les règles de la leçon n’exigent-elles pas d’écart d’ouverture (gap) entre les bougies ?","options":["Parce que les écarts d’ouverture sont interdits par le règlement général de la BRVM depuis sa création","Parce qu’un gap rendrait la figure plus fiable","Parce que les bougies de la BRVM n’ont jamais de mèche","Parce qu’à la BRVM l’ouverture égale souvent la clôture de la veille (40,9 % des séances)"],"correct":3,"explication":"Sur 25 330 séances dont l’ouverture est connue, 10 357 ont ouvert exactement à la clôture de la veille. Exiger un gap, comme la définition classique, éliminerait presque toutes les figures."},{"question":"Sur les dix actions les plus échangées, de 2021 à 2026, après un avalement baissier, la clôture était plus basse 5 séances plus tard dans quelle part des cas ?","options":["33,6 %","52,0 %","75,0 %","90,0 %"],"correct":0,"explication":"33,6 % sur 125 cas, contre 42,0 % pour une séance quelconque : la baisse a suivi MOINS souvent que d’habitude, et l’écart n’est pas établi."},{"question":"Que conclure de la mesure des figures sur les séances réelles de la BRVM ?","options":["Que les figures haussières garantissent une hausse dans les cinq séances qui suivent leur apparition","Qu’aucune figure n’a montré d’avantage établi dans le sens de sa lecture","Que les figures baissières annoncent toujours une baisse","Que les bougies ne s’appliquent pas aux actions"],"correct":1,"explication":"Les parts mesurées après chaque figure restent dans l’intervalle de hasard autour de celle d’une séance quelconque : une figure décrit une séance, elle ne la prolonge pas."},{"question":"Une séance n’a pas d’ouverture, de plus haut ni de plus bas publiés. Comment la lire ?","options":["Comme un doji, puisque les quatre prix sont égaux","Comme un marteau si la clôture monte","Seule la clôture est connue : aucune bougie ne peut être lue","En recopiant la clôture de la veille comme ouverture, et celle du jour comme plus haut"],"correct":2,"explication":"Sans prix publiés, toute bougie serait inventée. WESTBOURSE affiche alors la clôture seule et ne repère aucune figure."},{"question":"Comment confirmer une configuration de chandeliers ?","options":["Par la couleur de la dernière bougie du graphique affiché","Par la séance suivante et par le volume","Par le PER de la société","Elle n’a pas besoin de confirmation"],"correct":1,"explication":"Une figure ne devient intéressante qu’une fois confirmée par les séances suivantes, sur un volume réel."}],"qcm":{"question":"De quoi se compose une étoile du matin ?","options":["Trois hausses franches de suite, chacune clôturant plus haut que la précédente et ouvrant dans le corps de la veille","Une petite bougie contenue dans le corps d’une grande","Une grande baisse, une séance hésitante, puis une hausse qui reprend plus de la moitié de la baisse","Une seule bougie à longue mèche basse"],"correct":2,"explication":"Trois bougies : une grande baissière, une petite bougie d’hésitation, puis une haussière qui clôture au-dessus du milieu du corps de la première."},"liens":[{"label":"Les fiches valeur et leurs graphiques","href":"/actions"},{"label":"Le scanner technique","href":"/scanner"},{"label":"La liquidité de chaque valeur","href":"/liquidite"}],"avertissement":"Ceci n’est pas un conseil en investissement. Un indicateur technique décrit le passé des cours ; il ne prédit pas l’avenir. Les figures de bougies décrivent un comportement de marché, elles ne garantissent aucun mouvement futur. Investir en actions comporte un risque de perte en capital."}$wb$::jsonb),
         updated_at = now()
   where slug = 'academy-niveau-3-technique';

  raise notice '0262 : leçon 2 du niveau 3 recentrée';
end
$do$;

commit;

-- Vérification : titre, sections, simulateurs de bougies.
-- select c.content->'lessons'->2->>'titre', jsonb_array_length(c.content->'lessons'->2->'sections'),
--        c.content->'lessons'->2->'nouveaute'
--   from public.academy_courses c where c.slug = 'academy-niveau-3-technique';
